SET NOCOUNT ON; SET XACT_ABORT ON;
TRUNCATE TABLE stg.Limpia;
INSERT etl.Rechazos SELECT @Lote,archivo,fila_archivo,motivo,anio_original,mes_original,atenciones_original FROM stg.v_Normalizada CROSS APPLY(SELECT CONCAT(CASE WHEN anio_num IS NULL OR NOT EXISTS(SELECT 1 FROM etl.AniosPermitidos y WHERE y.anio=anio_num) THEN N'ANIO_INVALIDO; ' ELSE N'' END,CASE WHEN mes_num IS NULL OR mes_num NOT BETWEEN 1 AND 12 THEN N'MES_INVALIDO; ' ELSE N'' END,CASE WHEN atenciones_num IS NULL OR atenciones_num < 0 THEN N'ATENCIONES_INVALIDAS; ' ELSE N'' END,CASE WHEN CHARINDEX(NCHAR(65533),CONCAT(REGION,PROVINCIA,DISTRITO,IPRESS,DESC_SERVICIO) COLLATE Latin1_General_100_BIN2)>0 THEN N'TEXTO_CON_REEMPLAZO; ' ELSE N'' END,CASE WHEN COD_IPRESS=N'NO INFORMADO' OR COD_SERVICIO=N'NO INFORMADO' THEN N'CODIGO_OBLIGATORIO_AUSENTE; ' ELSE N'' END,CASE WHEN LEN(REGION)>150 OR LEN(PROVINCIA)>150 OR LEN(DISTRITO)>150 OR LEN(UBIGEO_DISTRITO)>20 OR LEN(COD_IPRESS)>50 OR LEN(COD_SERVICIO)>50 OR LEN(COD_UNIDAD_EJECUTORA)>50 OR LEN(NIVEL_EESS)>50 OR LEN(PLAN_SEGURO)>100 OR LEN(SEXO)>50 OR LEN(GRUPO_EDAD)>100 OR LEN(IPRESS)>400 OR LEN(DESC_SERVICIO)>400 OR LEN(DESC_UNIDAD_EJECUTORA)>400 THEN N'LONGITUD_EXCEDIDA; ' ELSE N'' END) motivo) q WHERE motivo<>N'' OPTION(MAXDOP 1, MAX_GRANT_PERCENT=1);
INSERT stg.Limpia([archivo],[fila_archivo],[id_raw],[clave_origen],[version_origen],[ANIO],[MES],[REGION],[PROVINCIA],[UBIGEO_DISTRITO],[DISTRITO],[COD_UNIDAD_EJECUTORA],[DESC_UNIDAD_EJECUTORA],[COD_IPRESS],[IPRESS],[NIVEL_EESS],[PLAN_SEGURO],[COD_SERVICIO],[DESC_SERVICIO],[SEXO],[GRUPO_EDAD],[ATENCIONES],[ubigeo_valido],[clave_ipress],[clave_servicio],[clave_unidad]) SELECT archivo,fila_archivo,id_raw,clave_origen,version_origen,anio_num,mes_num,[REGION],[PROVINCIA],[UBIGEO_DISTRITO],[DISTRITO],[COD_UNIDAD_EJECUTORA],[DESC_UNIDAD_EJECUTORA],[COD_IPRESS],[IPRESS],[NIVEL_EESS],[PLAN_SEGURO],[COD_SERVICIO],[DESC_SERVICIO],[SEXO],[GRUPO_EDAD],atenciones_num,CASE WHEN LEN(UBIGEO_DISTRITO)=6 AND UBIGEO_DISTRITO NOT LIKE '%[^0-9]%' AND LEFT(UBIGEO_DISTRITO,2) BETWEEN '01' AND '25' THEN 1 ELSE 0 END,HASHBYTES('SHA2_256',CONCAT([COD_IPRESS],NCHAR(31),[IPRESS],NCHAR(31),[NIVEL_EESS],NCHAR(31),[UBIGEO_DISTRITO],NCHAR(31),[DISTRITO],NCHAR(31),[PROVINCIA],NCHAR(31),[REGION],NCHAR(31),[COD_UNIDAD_EJECUTORA],NCHAR(31),[DESC_UNIDAD_EJECUTORA])),HASHBYTES('SHA2_256',CONCAT([COD_SERVICIO],NCHAR(31),[DESC_SERVICIO])),HASHBYTES('SHA2_256',CONCAT([COD_UNIDAD_EJECUTORA],NCHAR(31),[DESC_UNIDAD_EJECUTORA])) FROM stg.v_Normalizada CROSS APPLY(SELECT CONCAT(CASE WHEN anio_num IS NULL OR NOT EXISTS(SELECT 1 FROM etl.AniosPermitidos y WHERE y.anio=anio_num) THEN N'ANIO_INVALIDO; ' ELSE N'' END,CASE WHEN mes_num IS NULL OR mes_num NOT BETWEEN 1 AND 12 THEN N'MES_INVALIDO; ' ELSE N'' END,CASE WHEN atenciones_num IS NULL OR atenciones_num < 0 THEN N'ATENCIONES_INVALIDAS; ' ELSE N'' END,CASE WHEN CHARINDEX(NCHAR(65533),CONCAT(REGION,PROVINCIA,DISTRITO,IPRESS,DESC_SERVICIO) COLLATE Latin1_General_100_BIN2)>0 THEN N'TEXTO_CON_REEMPLAZO; ' ELSE N'' END,CASE WHEN COD_IPRESS=N'NO INFORMADO' OR COD_SERVICIO=N'NO INFORMADO' THEN N'CODIGO_OBLIGATORIO_AUSENTE; ' ELSE N'' END,CASE WHEN LEN(REGION)>150 OR LEN(PROVINCIA)>150 OR LEN(DISTRITO)>150 OR LEN(UBIGEO_DISTRITO)>20 OR LEN(COD_IPRESS)>50 OR LEN(COD_SERVICIO)>50 OR LEN(COD_UNIDAD_EJECUTORA)>50 OR LEN(NIVEL_EESS)>50 OR LEN(PLAN_SEGURO)>100 OR LEN(SEXO)>50 OR LEN(GRUPO_EDAD)>100 OR LEN(IPRESS)>400 OR LEN(DESC_SERVICIO)>400 OR LEN(DESC_UNIDAD_EJECUTORA)>400 THEN N'LONGITUD_EXCEDIDA; ' ELSE N'' END) motivo) q WHERE motivo=N'' OPTION(MAXDOP 1, MAX_GRANT_PERCENT=1);

IF EXISTS(SELECT 1 FROM etl.Rechazos WHERE id_lote=@Lote)
 BEGIN UPDATE etl.Lotes SET filas_aceptadas=(SELECT COUNT_BIG(*) FROM stg.Limpia),filas_rechazadas=(SELECT COUNT_BIG(*) FROM etl.Rechazos WHERE id_lote=@Lote) WHERE id_lote=@Lote;
 THROW 51302,'Snapshot invalido: se registraron rechazos. No se publica parcialmente un mes.',1; END;

IF @Modo='SQL' AND EXISTS(SELECT 1 FROM raw.Registros r JOIN SIS_NORMALIZADA.oltp.OrigenVersion v ON v.clave_origen=r.clave_origen WHERE r.id_lote=@Lote AND r.version_origen<=v.version) THROW 52006,'Version SQL anterior o igual a la publicada.',1;
UPDATE etl.Lotes SET filas_aceptadas=(SELECT COUNT_BIG(*) FROM stg.Limpia),filas_rechazadas=0,estado='VALIDADO' WHERE id_lote=@Lote;

